def _manifest_is_well_formed(self, manifest: Any) -> bool:
    # 清单结构校验（阶段一“清单非法”）：恰含八键且类型/取值合法。
    if not isinstance(manifest, dict):
        return False
    expected = {
        "snapshot",
        "filters",
        "count",
        "alg",
        "digest",
        "signer_did",
        "key_version",
        "signature",
    }
    if set(manifest) != expected:
        return False

    def _is_nonneg_int(value: Any) -> bool:
        return (
            isinstance(value, int)
            and not isinstance(value, bool)
            and value >= 0
        )

    def _is_positive_int(value: Any) -> bool:
        return (
            isinstance(value, int)
            and not isinstance(value, bool)
            and value >= 1
        )

    if not _is_nonneg_int(manifest["snapshot"]):
        return False
    if not _is_nonneg_int(manifest["count"]):
        return False
    if manifest["alg"] != "SHA-256":
        return False
    if not (
        isinstance(manifest["digest"], str)
        and _SHA256_HEX_RE.fullmatch(manifest["digest"])
    ):
        return False
    if (
        not isinstance(manifest["signer_did"], str)
        or not manifest["signer_did"]
    ):
        return False
    if not _is_positive_int(manifest["key_version"]):
        return False
    if (
        not isinstance(manifest["signature"], str)
        or not manifest["signature"]
    ):
        return False

    filters = manifest["filters"]
    if not isinstance(filters, dict):
        return False
    if set(filters) != {
        "after",
        "limit",
        "did",
        "key_version",
        "from",
        "to",
    }:
        return False
    if filters["after"] is not None and not _is_nonneg_int(
        filters["after"]
    ):
        return False
    limit = filters["limit"]
    if limit is not None and not (
        _is_positive_int(limit) and 1 <= limit <= 10000
    ):
        return False
    if filters["did"] is not None and not (
        isinstance(filters["did"], str) and filters["did"]
    ):
        return False
    if filters["key_version"] is not None and not _is_positive_int(
        filters["key_version"]
    ):
        return False
    from_time = filters["from"]
    to_time = filters["to"]
    if from_time is not None:
        try:
            _parse_utc_z_query(from_time, "from")
        except ValidationError:
            return False
    if to_time is not None:
        try:
            _parse_utc_z_query(to_time, "to")
        except ValidationError:
            return False
    if (
        from_time is not None
        and to_time is not None
        and from_time > to_time
    ):
        return False
    return True

def _post_trust_did_deactivations_manifest_verify(
    self, tenant: str
) -> None:
    # POST /v1/trust/dids/deactivations/manifest/verify：校验一次
    # 导出清单与其 NDJSON 内容。外层请求错误（非法 JSON/非对象/
    # 缺漏或多余字段/manifest 非对象/ndjson 非字符串）一律 400 且
    # 仅 {"error": ...}。外层合法后任何失败均 HTTP 200，按顺序
    # 返回 {"valid":false,"reason":...}：清单非法 -> 锚点不可用
    # （本租户同 did/版本 active 锚点）-> 签名格式错误 -> 签名
    # 校验失败 -> 导出内容不匹配（UTF-8 SHA-256 摘要及行数）。
    # 成功仅 {"valid":true}。纯只读、租户隔离、不记审计。
    data = self._read_json()
    if set(data) != {"manifest", "ndjson"}:
        missing = [f for f in ("manifest", "ndjson") if f not in data]
        if missing:
            raise ValidationError(
                f"请求缺少字段: {', '.join(missing)}"
            )
        extra = sorted(set(data) - {"manifest", "ndjson"})
        raise ValidationError(f"请求含多余字段: {', '.join(extra)}")
    manifest = data["manifest"]
    ndjson = data["ndjson"]
    if not isinstance(manifest, dict):
        raise ValidationError(
            "请求不合法: 字段 manifest 必须为 JSON 对象"
        )
    if not isinstance(ndjson, str):
        raise ValidationError(
            "请求不合法: 字段 ndjson 必须为字符串"
        )

    reason = self._verify_deactivation_manifest_item(
        tenant, manifest, ndjson
    )
    if reason is not None:
        self._send_json(200, {"valid": False, "reason": reason})
        return
    self._send_json(200, {"valid": True})

def _verify_deactivation_manifest_item(
    self, tenant: str, manifest: Any, ndjson: str
) -> Optional[str]:
    # 单项清单验真（供单项与批量端点共用）：按序返回失败原因
    # （清单非法 -> 锚点不可用 -> 签名格式错误 -> 签名校验失败
    # -> 导出内容不匹配），成功返回 None。纯只读。
    # 阶段一：清单结构
    if not self._manifest_is_well_formed(manifest):
        return "清单非法"

    signer_did = manifest["signer_did"]
    key_version = manifest["key_version"]

    # 阶段二：本租户同 did/版本 active 信任锚点（须含
    # deactivation 用途，否则按锚点不可用处理）
    public_pem = store.get_active_trust_anchor_public_key(
        tenant, signer_did, key_version, required_use="deactivation"
    )
    if public_pem is None:
        return "锚点不可用"
    try:
        crypto.validate_public_key_pem(public_pem)
    except (ValueError, TypeError):
        return "锚点不可用"

    signed = {
        "snapshot": manifest["snapshot"],
        "filters": manifest["filters"],
        "count": manifest["count"],
        "alg": manifest["alg"],
        "digest": manifest["digest"],
        "signer_did": signer_did,
        "key_version": key_version,
    }
    signature = manifest["signature"]

    # 阶段三：签名格式
    try:
        crypto.validate_signature_format_strict(signature)
    except crypto.MalformedSignature:
        return "签名格式错误"

    # 阶段四：密码学验签
    try:
        crypto.verify(signed, signature, public_pem)
    except crypto.MalformedSignature:
        return "签名格式错误"
    except crypto.InvalidSignature:
        return "签名校验失败"
    except Exception:  # noqa: BLE001 验签绝不向上抛错或泄露细节
        return "签名校验失败"

    # 阶段五：导出内容——UTF-8 字节的 SHA-256 摘要与行数
    try:
        raw = ndjson.encode("utf-8")
    except UnicodeEncodeError:
        return "导出内容不匹配"
    actual_digest = hashlib.sha256(raw).hexdigest()
    line_count = raw.count(b"\n")
    if (
        actual_digest != manifest["digest"]
        or line_count != manifest["count"]
    ):
        return "导出内容不匹配"
    return None

def _post_trust_did_deactivations_manifest_verify_batch(
    self, tenant: str
) -> None:
    # POST /v1/trust/dids/deactivations/manifest/verify-batch：
    # 批量校验停用通告清单与 NDJSON。任何失败都返回 HTTP 200。
    # 请求体须恰为 {"items": [项...]}，数组非空且不超过 100 项；
    # 请求体非法（空体、非法 JSON、非对象、字段缺失或多余、items
    # 非数组、空数组或超过上限）时返回
    # {"results": [], "reason": "请求..."}。请求级合法时返回
    # {"results": [...]}，长度与顺序与输入一致，逐项复用单项验真
    # 规则，失败不短路；每项须恰含 manifest 对象与 ndjson 字符串，
    # 项非对象、字段或类型非法按“清单非法”处理。成功项仅
    # {"valid": true}，失败项 {"valid": false, "reason": ...}。
    # 纯只读：不写状态、历史或审计，仅使用当前租户锚点。
    try:
        length = int(self.headers.get("Content-Length") or 0)
        raw = self.rfile.read(length) if length > 0 else b""
    except (ValueError, TypeError):
        self._send_json(
            200,
            {"results": [],
             "reason": "请求不合法: 请求体缺失或长度声明非法"},
        )
        return
    except Exception:  # noqa: BLE001
        self._send_json(
            200, {"results": [], "reason": "请求不合法: 请求体读取失败"}
        )
        return
    if not raw:
        self._send_json(
            200, {"results": [], "reason": "请求不合法: 请求体缺失"}
        )
        return
    try:
        data = json.loads(raw.decode("utf-8"))
    except UnicodeDecodeError:
        self._send_json(
            200,
            {"results": [],
             "reason": "请求不合法: 请求体不是合法 UTF-8 文本"},
        )
        return
    except json.JSONDecodeError:
        self._send_json(
            200, {"results": [], "reason": "请求不合法: 请求体不是合法 JSON"}
        )
        return

    def _request_invalid(reason: str) -> None:
        self._send_json(200, {"results": [], "reason": reason})

    if not isinstance(data, dict):
        _request_invalid("请求不合法: 请求体必须为 JSON 对象")
        return
    if set(data) != {"items"}:
        if "items" not in data:
            _request_invalid("请求缺少字段: items")
            return
        extra = sorted(set(data) - {"items"})
        _request_invalid(f"请求含多余字段: {', '.join(extra)}")
        return
    items = data["items"]
    if not isinstance(items, list):
        _request_invalid("请求不合法: 字段 items 必须为数组")
        return
    if not items:
        _request_invalid("请求不合法: items 数组不能为空")
        return
    if len(items) > 100:
        _request_invalid(
            "请求不合法: items 数组不能超过 100 项"
            f"（当前 {len(items)} 项）"
        )
        return

    results: List[Dict[str, Any]] = []
    for item in items:  # 顺序校验，失败不短路
        if (
            not isinstance(item, dict)
            or set(item) != {"manifest", "ndjson"}
            or not isinstance(item["manifest"], dict)
            or not isinstance(item["ndjson"], str)
        ):
            results.append({"valid": False, "reason": "清单非法"})
            continue
        reason = self._verify_deactivation_manifest_item(
            tenant, item["manifest"], item["ndjson"]
        )
        if reason is None:
            results.append({"valid": True})
        else:
            results.append({"valid": False, "reason": reason})
    self._send_json(200, {"results": results})

def _put_trust_anchor_status(
    self, tenant: str, did: str, key_version: str
) -> None:
    # 请求体必须恰为 {"status": "revoked"}；路径 key_version
    # 须为非布尔正整数（路径参数为字符串）。
    data = self._read_json()
    if "status" not in data:
        raise ValidationError("缺少字段: status")
    extra = sorted(set(data) - {"status"})
    if extra:
        raise ValidationError(f"多余字段: {', '.join(extra)}")
    if data["status"] != "revoked":
        raise ValidationError(
            f"字段 status 非法: {data['status']!r}（仅支持 revoked）"
        )
    if (
        not key_version
        or any(ch < "0" or ch > "9" for ch in key_version)
        or int(key_version) < 1
    ):
        raise ValidationError("路径参数 key_version 必须为正整数")
    record = store.revoke_trust_anchor(tenant, did, int(key_version))
    # 首次吊销与幂等重试均 200，updated_at 保持首次值
    self._send_json(200, self._trust_anchor_payload(record))

def _put_trust_anchor_uses(
    self, tenant: str, did: str, key_version: str
) -> None:
    # PUT /v1/trust/anchors/{did}/{key_version}/uses：收紧锚点
    # 版本的用途白名单（无需轮换即可撤销用途）。请求体必须恰含
    # from_uses、uses，两者均须为非空无重复字符串数组、取值限
    # 且按规范序；路径 key_version 须为 ASCII 十进制正整数。
    # 未知或跨租户锚点 404，已吊销 409；目标等于当前值幂等
    # 200 且无副作用，否则 from_uses 须等于当前值且目标为其
    # 真子集，前置不匹配或扩权均 409。200 按键序恰返 did、
    # key_version、uses；实际变更仅记一次

def _post_trust_credential_status_receipt_consumptions_manifest_verify_batch(
    self, tenant: str
) -> None:
    # POST /v1/trust/credential-status/receipt/consumptions/
    # manifest/verify-batch：批量校验凭证状态回执消费历史清单与
    # NDJSON。任何失败都返回 HTTP 200。请求体须恰为
    # {"items": [项...]}，数组非空且不超过 100 项；空体、非法
    # JSON、非对象、键集错误、items 非数组、空数组或超限一律按键
    # 序恰返 {"results": [], "reason": "请求非法"}。合法批次返回
    # {"results": [...]}，长度与顺序与输入一致，逐项不短路；每项
    # 须恰含 manifest 对象与 ndjson 字符串，项非对象、字段或类型
    # 非法按“清单非法”处理，其余复用单项验真协议。成功项仅
    # {"valid": true}，失败项键序恰为 valid、reason，reason 恰为
    # 五种原因之一。批初在同一把锁内原子读取本租户锚点快照，
    # 并发吊销或用途收紧不会产生批内混合结论。纯只读：不写状态、
    # 历史或审计，结论跨重启稳定。
    def _request_invalid() -> None:
        self._send_json(
            200, {"results": [], "reason": "请求非法"}
        )

    try:
        length = int(self.headers.get("Content-Length") or 0)
        raw = self.rfile.read(length) if length > 0 else b""
    except (ValueError, TypeError):
        _request_invalid()
        return
    except Exception:  # noqa: BLE001
        _request_invalid()
        return
    if not raw:
        _request_invalid()
        return
    try:
        data = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError):
        # ValueError 含 JSON 解析错误与超长十进制整数位数上限。
        _request_invalid()
        return
    if not isinstance(data, dict) or set(data) != {"items"}:
        _request_invalid()
        return
    items = data["items"]
    if (
        not isinstance(items, list)
        or not items
        or len(items) > 100
    ):
        _request_invalid()
        return

    # 先判定每项外层结构并收集结构合法项的锚点查询，批初原子
    # 读取一次本租户锚点快照（required_use 恒为 status）。
    well_formed: List[bool] = []
    queries: List[Tuple[str, int, str]] = []
    for item in items:
        if (
            isinstance(item, dict)
            and set(item) == {"manifest", "ndjson"}
            and isinstance(item["manifest"], dict)
            and isinstance(item["ndjson"], str)
            and self._receipt_consumption_manifest_is_well_formed(
                item["manifest"]
            )
        ):
            well_formed.append(True)
            queries.append(
                (
                    item["manifest"]["signer_did"],
                    item["manifest"]["key_version"],
                    "status",
                )
            )
        else:
            well_formed.append(False)

    snapshot_pems = (
        store.get_active_trust_anchor_public_key_snapshot(
            tenant, queries
        )
        if queries
        else []
    )
    anchor_snapshot: Dict[Tuple[str, int], Optional[str]] = {}
    for (did, key_version, _use), public_pem in zip(
        queries, snapshot_pems
    ):
        anchor_snapshot[(did, key_version)] = public_pem

    results: List[Dict[str, Any]] = []
    for index, item in enumerate(items):  # 顺序校验，失败不短路
        if not well_formed[index]:
            results.append({"valid": False, "reason": "清单非法"})
            continue
        reason = self._verify_credential_status_receipt_consumption_manifest_item(
            tenant,
            item["manifest"],
            item["ndjson"],
            anchor_snapshot=anchor_snapshot,
        )
        if reason is None:
            results.append({"valid": True})
        else:
            results.append({"valid": False, "reason": reason})
    self._send_json(200, {"results": results})

def _post_trust_credential_status_receipt_sync(
    self, tenant: str
) -> None:
    # POST /v1/trust/credential-status/receipt-sync：同步外系统
    # 凭证状态回执消费历史并防重放。除下列差异外，请求结构、
    # 400 外层错误、清单验真五阶段及固定 reason、游标窗口、检查点
    # 续页与重放/409 冲突、201/200 成功响应、500 回滚、并发、
    # 重启与不审计语义完整复用 POST /v1/trust/receipt-sync：
    # 1) 清单验真锚点用途改为 status（复用凭证状态回执消费历史
    #    清单验真）；
    # 2) NDJSON 逐字复用同目录凭证状态回执消费历史 export；
    # 3) 检查点与同步索引独立于普通验真回执同步，仍按租户、
    #    signer_did 隔离；
    # 4) 成功响应键序恰为 valid、signer_did、snapshot、
    #    next_after、count。
    data = self._read_json()
    if set(data) != {"manifest", "ndjson"}:
        missing = [f for f in ("manifest", "ndjson") if f not in data]
        if missing:
            raise ValidationError(
                f"请求缺少字段: {', '.join(missing)}"
            )
        extra = sorted(set(data) - {"manifest", "ndjson"})
        raise ValidationError(f"请求含多余字段: {', '.join(extra)}")
    manifest = data["manifest"]
    ndjson = data["ndjson"]
    if not isinstance(manifest, dict):
        raise ValidationError(
            "请求不合法: 字段 manifest 必须为 JSON 对象"
        )
    if not isinstance(ndjson, str):
        raise ValidationError(
            "请求不合法: 字段 ndjson 必须为字符串"
        )

    # 阶段一：清单验真（锚点用途为 status，五段固定 reason）。
    reason = (
        self._verify_credential_status_receipt_consumption_manifest_item(
            tenant, manifest, ndjson
        )
    )
    if reason is not None:
        self._send_json(200, {"valid": False, "reason": reason})
        return

    signer_did = manifest["signer_did"]
    snapshot = manifest["snapshot"]
    after = manifest["filters"]["after"]

    # 阶段二：NDJSON 结构、游标窗口与页内重复键（与普通回执
    # 同步同一解析协议，行形状逐字复用状态回执消费历史 export）。
    events = self._parse_receipt_sync_ndjson(
        ndjson, after, snapshot
    )
    if events is None:
        self._send_json(
            200, {"valid": False, "reason": "导出内容非法"}
        )
        return

    # 阶段三：独立检查点推进、历史重复键与原子落盘。
    try:
        created, effective_snapshot, next_after, count = (
            store.sync_credential_status_receipt_consumptions(
                tenant, signer_did, snapshot, after, events
            )
        )
    except ConflictError:
        self._send_error(409, "同步游标冲突")
        return
    except ValidationError:
        self._send_json(
            200, {"valid": False, "reason": "导出内容非法"}
        )
        return
    except StorageError:
        self._send_error(500, "存储失败")
        return
    self._send_json(
        201 if created else 200,
        {
            "valid": True,
            "signer_did": signer_did,
            "snapshot": effective_snapshot,
            "next_after": next_after,
            "count": count,
        },
    )

def _post_trust_credential_status_receipt_sync_batch(
    self, tenant: str
) -> None:
    # POST /v1/trust/credential-status/receipt-sync-batch：批量
    # 同步外系统凭证状态回执消费历史，任何失败都返回 HTTP 200。

def _verify_credential_status_receipt_consumption_manifest_item(
    self,
    tenant: str,
    manifest: Any,
    ndjson: str,
    anchor_snapshot: Optional[
        Dict[Tuple[str, int], Optional[str]]
    ] = None,
) -> Optional[str]:
    # 单项凭证状态回执消费历史清单验真：按序返回失败原因（清单
    # 非法 -> 锚点不可用 -> 签名格式错误 -> 签名校验失败 ->
    # 导出内容不匹配），成功返回 None。锚点须为本租户同
    # did/版本 active 且含 status 用途。anchor_snapshot 给定时为
    # 批量端点在批初原子取得的本租户锚点快照（键 did/版本，值为
    # 公钥 PEM 或 None），不再即时读锚点；为 None 时按单项协议
    # 即时读取。纯只读。
    # 阶段一：清单结构（与验真回执消费历史清单同一结构校验）
    if not self._receipt_consumption_manifest_is_well_formed(manifest):
        return "清单非法"

    signer_did = manifest["signer_did"]
    key_version = manifest["key_version"]

    # 阶段二：本租户同 did/版本且含 status 用途的 active 信任锚点
    if anchor_snapshot is None:
        public_pem = store.get_active_trust_anchor_public_key(
            tenant, signer_did, key_version, required_use="status"
        )
    else:
        public_pem = anchor_snapshot[(signer_did, key_version)]
    if public_pem is None:
        return "锚点不可用"
    try:
        crypto.validate_public_key_pem(public_pem)
    except (ValueError, TypeError):
        return "锚点不可用"

    signed = {
        "snapshot": manifest["snapshot"],
        "filters": manifest["filters"],
        "count": manifest["count"],
        "alg": manifest["alg"],
        "digest": manifest["digest"],
        "signer_did": signer_did,
        "key_version": key_version,
    }
    signature = manifest["signature"]

    # 阶段三：签名格式
    try:
        crypto.validate_signature_format_strict(signature)
    except crypto.MalformedSignature:
        return "签名格式错误"

    # 阶段四：密码学验签
    try:
        crypto.verify(signed, signature, public_pem)
    except crypto.MalformedSignature:
        return "签名格式错误"
    except crypto.InvalidSignature:
